    return jdbc.update("UPDATE allocation SET held_amount = held_amount + ?, updated_nanos = ?,"
            + " quota_version = quota_version + 1"
            + " WHERE allocation_key = ? AND held_amount + ? >= 0",
            netChange, updatedNanos, allocationKey, netChange);
}

