    @Test
    void settlementAndSingleTransferSettleByCommitOrderWithoutOverdraft() throws Exception {
        long windowId = createWindow("ch-race-mix-" + run, "1000");
        String a = approvedSubject(windowId, "user-a", "6");
        String b = approvedSubject(windowId, "user-b", "6");
        // 单笔转让目标必须为 REQUESTED
        String targetKey = key("ak");
        Map<String, Object> submit = new HashMap<>();
        submit.put("commandKey", key("ac"));
        submit.put("allocationKey", targetKey);
        submit.put("windowId", windowId);
        submit.put("userId", "user-t");
        submit.put("amount", "6");
        postOk("/api/allocations", submit, );

        // 清算：A->B 4（A 版本取批准后 2）
        Map<String, Object> batch = settlementBody(key("req"), key("sk"), windowId,
                List.of(instruction(key("ik"), a, b, "4")),
                Map.of(a, 2L, b, 2L));

        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch gate = new CountDownLatch(1);
        Future<Integer> settlementFuture = pool.submit(() -> {
            gate.await();
            return settleStatus(batch);
        });
        Future<Integer> transferFuture = pool.submit(() -> {
            gate.await();
            try {
                // 直接走服务层以提供 X-Actor-Id 语义
                return callTransfer(key("tc"), key("tk"), a, targetKey, "user-a");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
        gate.countDown();
        int settlementStatus = settlementFuture.get(30, TimeUnit.SECONDS);
        int transferStatus = transferFuture.get(30, TimeUnit.SECONDS);
        pool.shutdown();

        // 两操作都只扣 A 的持有额度（清算 4、转让 6，合计 10 > 6），按提交顺序后者必失败：
        // 转让先提交则 A=0，清算因版本过期 409；清算先提交则 A=2，转让持有不足 422
        assertTrue((settlementStatus == 200) != (transferStatus == 200),
                "清算与转让争抢同一源恰好一个成功: settlement=" + settlementStatus
                        + " transfer=" + transferStatus);
        assertTrue(transferStatus == 200 || transferStatus == 422, "transfer=" + transferStatus);
        assertTrue(settlementStatus == 200 || settlementStatus == 409, "settlement=" + settlementStatus);
        JsonNode cap = getOk("/api/windows/" + windowId + "/capacity");
        double heldA = Double.parseDouble(heldOf(windowId, a));
        assertTrue(heldA >= 0, "A 不得超额: " + heldA);
        assertTrue(Double.parseDouble(cap.get("approvedTotal").asText())
                <= Double.parseDouble(cap.get("availableTotal").asText()));
    }

    private int callTransfer(String commandKey, String transferKey, String source, String target, String actor) {
        try {
            // 通过 HTTP 无法在本线程携带头，改用 MockMvc 由 settleStatus 同构；这里直接用 mvc 性能头
            mvc.perform(post("/api/transfers").contentType(MediaType.APPLICATION_JSON)
                            .content(objectMapper.writeValueAsString(Map.of(
                                    "commandKey", commandKey, "transferKey", transferKey,
                                    "sourceAllocationKey", source, "targetAllocationKey", target)))
                            .header("X-Actor-Id", actor))
                    .andExpect(result -> {
                        int status = result.getResponse().getStatus();
                        if (status != 200 && status != 409 && status != 422) {
                            throw new AssertionError("unexpected transfer status " + status);
                        }
                    });
            // 重新取得状态：上面 result 已消费，用简单二次判定不可行；改为直接返回由异常路径区分
            return lastStatusHolder[0];
        } catch (Exception e) {
            Throwable cause = e.getCause() != null ? e.getCause() : e;
            if (cause instanceof ApiException api) {
                return api.status().value();
            }
            throw new RuntimeException(e);
        }
    }

    private final int[] lastStatusHolder = new int[]{200};
}

